import { describe, expect, it } from 'vitest';
import type { z } from 'zod';
import type { paths } from '$lib/api/schema';
import * as schemas from '$lib/api/zod/zod.gen';

// The zod schemas (runtime validation) and schema.d.ts (static types) are generated by two tools
// from the same contract. These checks fail the type check (`bun run check`, part of verify) as
// soon as one of them describes a response the other does not.

// `never` on both sides (an unresolved path) must not pass for "the same type".
type Equals<A, B> = [A] extends [never]
	? false
	: (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2
		? true
		: false;

type Json<
	Path extends keyof paths,
	Method extends keyof paths[Path]
> = paths[Path][Method] extends {
	responses: { 200: { content: { 'application/json': infer Body } } };
}
	? Body
	: paths[Path][Method] extends {
				responses: { 201: { content: { 'application/json': infer Body } } };
		  }
		? Body
		: never;

type DataOf<Body> = Body extends { data: infer Data } ? Data : never;
type Inferred<Schema extends z.ZodType> = DataOf<z.infer<Schema>>;

// Each line is a compile-time assertion: `true` only when both sides are the same type.
const sameData = {
	listUsers: true satisfies Equals<
		Inferred<typeof schemas.zListUsersResponse>,
		DataOf<Json<'/api/v1/users', 'get'>>
	>,
	createUser: true satisfies Equals<
		Inferred<typeof schemas.zCreateUserResponse>,
		DataOf<Json<'/api/v1/users', 'post'>>
	>,
	getUser: true satisfies Equals<
		Inferred<typeof schemas.zGetUserResponse>,
		DataOf<Json<'/api/v1/users/{id}', 'get'>>
	>,
	listUserTasks: true satisfies Equals<
		Inferred<typeof schemas.zListUserTasksResponse>,
		DataOf<Json<'/api/v1/users/{id}/tasks', 'get'>>
	>,
	createTask: true satisfies Equals<
		Inferred<typeof schemas.zCreateTaskResponse>,
		DataOf<Json<'/api/v1/tasks', 'post'>>
	>,
	updateTask: true satisfies Equals<
		Inferred<typeof schemas.zUpdateTaskResponse>,
		DataOf<Json<'/api/v1/tasks/{id}', 'put'>>
	>,
	getStats: true satisfies Equals<
		Inferred<typeof schemas.zGetStatsResponse>,
		DataOf<Json<'/api/v1/stats', 'get'>>
	>
};

describe('generated zod schemas and generated types', () => {
	it('describe the same data for every validated operation (happy path)', () => {
		// GIVEN / WHEN: The compile-time comparisons above (checked by svelte-check).
		// THEN: All of them hold; at run time, each schema exists.
		expect(Object.values(sameData).every(Boolean)).toBe(true);
		expect(Object.keys(sameData)).toHaveLength(7);
	});

	it('types the stats counters as numbers, not bigint (boundary)', () => {
		// GIVEN / WHEN: The inferred type of a stats counter.
		const counter: z.infer<typeof schemas.zStats>['users'] = 2 ** 53 - 1;

		// THEN: It is a plain number (a bigint would not compile here nor pass at run time).
		expect(typeof counter).toBe('number');
		expect(true satisfies Equals<z.infer<typeof schemas.zStats>['users'], number>).toBe(true);
	});
});
